insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006511', '$\ln2$', 'A soma dos logaritmos é o logaritmo do produto. Esse produto até $N$ se simplifica para $2(N+1)/(N+2)$. Quando $N\to\infty$, o produto tende a $2$, e a soma tende a $\ln2$.') on conflict do nothing;
