insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000065111', '40000000-0000-4000-8000-000000006511', 'Passo 2', 'Quando $N\to\infty$, o produto tende a $2$, e a soma tende a $\ln2$.', '2') on conflict do nothing;
